mapper.select:
SELECT budget_adjust_id, budget_period_id, amount, memo, created_at, updated_at
FROM budget_adjust
WHERE user_id = #{userId}
  AND budget_period_id = #{budgetPeriodId}
ORDER BY created_at DESC, budget_adjust_id DESC

SELECT COALESCE(SUM(amount), 0)
FROM budget_adjust
WHERE user_id = #{userId}
  AND budget_period_id = #{budgetPeriodId}

SELECT budget_adjust_id, budget_period_id, amount, memo, created_at, updated_at
FROM budget_adjust
WHERE user_id = #{userId}
  AND budget_adjust_id = #{budgetAdjustId}

mapper.update:
UPDATE budget_adjust
SET amount = #{amount}, memo = #{memo,jdbcType=VARCHAR}
WHERE user_id = #{userId}
  AND budget_adjust_id = #{budgetAdjustId}

mapper.delete:
DELETE FROM budget_adjust
WHERE user_id = #{userId}
  AND budget_adjust_id = #{budgetAdjustId}
